def write():
 for slug,arts in D.items():
  units={f'art-{n}':dict(simples=s,pontos=[p],atencao=[a],exemplo=e+' Variação: '+v,prova=[q],termos=[],remissoes=[]) for n,(s,p,a,e,v,q) in arts.items()}
  if slug=='quimicos':
   for n in [1,2,4,5,6,7,9,12,13,14,20]:units[f'art-{n}']['remissoes']=[PF+'legislacao/legislacao']
   for n in [2,5,12,13,14]:units[f'art-{n}']['remissoes'].append(PF+'legislacao/in-338-2026.pdf')
  if slug=='cpf':
   for n,ref in [(2,'leis/1980-1988/l7116.htm'),(3,'leis/l9454.htm'),(4,'_ato2015-2018/2017/lei/l13444.htm'),(5,'_ato2015-2018/2017/lei/l13460.htm'),(8,'_ato2015-2018/2017/lei/l13444.htm')]:units[f'art-{n}']['remissoes']=[P+ref]
  if slug=='identidade':
   for n in [1,2,3,4,10,11]:units[f'art-{n}']['remissoes']=[P+'_ato2019-2022/2022/decreto/d10977.htm',P+'_ato2023-2026/2023/lei/l14534.htm']
   units['art-5']['remissoes']=[P+'decreto/2001/d3927.htm']
   units['art-9']['remissoes']=[P+'_ato2015-2018/2018/lei/l13726.htm']
  if slug=='menor-potencial-ofensivo':
   for n in [1,2,3,4,5,6,7]:units[f'art-{n}']['remissoes']=[P+'_ato2023-2026/2024/decreto/d12341.htm']
  Path(f'scripts/explicacoes/{slug}-revisao-aplicada-2026-10-11.json').write_text(json.dumps(dict(course_slug=slug,units=units),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 print(sum(map(len,D.values())),'explicitly authored articles')
if __name__=='__main__':write()
